//
// REGISTER_ORDER is imported, never hardcoded here (Law 7): compose.js is
// the single source of the register taxonomy in this view.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { REGISTER_ORDER } from '../js/compose.js';

const cssPath = fileURLToPath(new URL('../css/board.css', import.meta.url));
const css = readFileSync(cssPath, 'utf8');

// Extracts the `{ ... }` block belonging to a single top-level rule whose
// selector is exactly `.register-REGISTERID` (e.g. `.register-nominal`).
// Plain string/regex extraction, no CSS-parser dependency (the web view is
// deliberately dependency-free except the vendored validator).
function findRuleBlock(selector) {
  const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Selector must not be a prefix of a longer class name (e.g.
  // `.register-nominal` must not match inside `.register-nominal-foo`), so
  // require a non-word boundary (or `{`) right after it.
  const re = new RegExp(`${escaped}(?![\\w-])\\s*\\{([^}]*)\\}`);
  const match = css.match(re);
  return match ? match[1] : null;
}

for (const registerId of REGISTER_ORDER) {
  const selector = `.register-${registerId}`;

  test(`${selector} rule exists in board.css`, () => {
    assert.notEqual(findRuleBlock(selector), null, `expected a ${selector} rule block in board.css`);
  });

  test(`${selector} is color-self-contained: declares BOTH border-left-color and color, so no register can inherit another's color`, () => {
    const block = findRuleBlock(selector);
    assert.notEqual(block, null, `expected a ${selector} rule block in board.css`);
    assert.match(
      block,
      /border-left-color\s*:/,
      `${selector} must declare border-left-color`
    );
    assert.match(
      block,
      /(?<!-)\bcolor\s*:/,
      `${selector} must declare its own color (not just border-left-color) - otherwise this register's ` +
        `elements inherit color from an ancestor running a different register (issue #31)`
    );
  });
}

// compose.js - THE composition engine (design rev 5 S5.2 Rules 1-4; spec
// YB-6). Pure functions only: no DOM, no fetch, no clock reads - every
// input is a value already on the wire (a lane's position/freshness, the
// current snapshot's vocabularies.positions defs, and whether a renderer
// exists for this lane's payload shape). That purity is what makes the
// THREE-AXIS matrix (board/web/test/compose.test.js) exhaustively testable
// in Node with no browser.
import { describeVocab } from './vocab.js';

// The ONLY closed taxonomy (design S5.2) and its severity order. Growing
// this set is a constitution-level decision (schema/yard-snapshot.schema.json
// $defs.register's own description says the same).
export const REGISTER_ORDER = ['nominal', 'in-progress', 'needs-attention'];

function rank(register) {
  const i = REGISTER_ORDER.indexOf(register);
  // An unrecognised register STRING (not id - a register value itself)
  // is a discovery, not a silent "calm" - never let unknown sort as fine.
  return i === -1 ? REGISTER_ORDER.length : i;
}

// Rule 1: rendered register = MOST SEVERE of the axes given.
export function mostSevereRegister(...registers) {
  return registers.reduce((worst, r) => (rank(r) > rank(worst) ? r : worst), REGISTER_ORDER[0]);
}

// Position's register: from its def (vocabularies.positions); an
// unrecognised position id renders needs-attention (design Rule 1: "needs-
// attention if unrecognised").
export function positionRegister(positionId, positionDefs) {
  return describeVocab(positionId, positionDefs).register;
}

// Freshness's register: the design's closed mapping (S5.2):
// not-applicable -> nominal, never-polled -> in-progress, fresh -> nominal,
// stale -> needs-attention, failed -> needs-attention.
const FRESHNESS_REGISTER = {
  'not-applicable': 'nominal',
  'never-polled': 'in-progress',
  fresh: 'nominal',
  stale: 'needs-attention',
  failed: 'needs-attention'
};

export function freshnessRegister(freshness) {
  const kind = freshness && freshness.kind;
  return Object.prototype.hasOwnProperty.call(FRESHNESS_REGISTER, kind)
    ? FRESHNESS_REGISTER[kind]
    : 'needs-attention'; // an unrecognised freshness kind is a discovery too, never silence
}

// Capability's register: no renderer for this lane's payload shape resolves
// needs-attention - design Rule 1's load-bearing case: a live lane whose
// data source dies (or whose payload shape this view does not know how to
// render) resolves hot even when position and freshness both read calm.
export function capabilityRegister(hasRenderer) {
  return hasRenderer ? 'nominal' : 'needs-attention';
}

/**
 * The THREE-AXIS matrix function YB-6 pins: position register x freshness
 * kind x capability present/absent, most-severe-wins.
 *
 * @param {{position: string, positionDefs: Array, freshness: object, hasRenderer: boolean}} args
 */
export function composeRegister({ position, positionDefs, freshness, hasRenderer }) {
  return mostSevereRegister(
    positionRegister(position, positionDefs),
    freshnessRegister(freshness),
    capabilityRegister(hasRenderer)
  );
}

export const NO_RENDERER_LINE = 'no renderer for this payload';

function freshnessLine(freshness) {
  const kind = freshness && freshness.kind;
  switch (kind) {
    case 'not-applicable':
      // Rule 2: a lane that will never be read must never say "not yet read".
      return null;
    case 'never-polled':
      return 'not yet polled';
    case 'fresh':
      // Rule 3: rendered age is ALWAYS server-issued (ageBucketMs), and the
      // wire's "fresh" variant carries no ageBucketMs at all - only "stale"
      // does (schema/yard-snapshot.schema.json $defs.freshness's oneOf).
      // Showing a computed elapsed time here (the mockup's illustrative
      // "fresh, 2s ago") would mean computing age from the client's own
      // clock off `asOf`, which Rule 3 forbids outright. Disclosed steering
      // deviation from the mock's illustrative text; the contract wins.
      return 'fresh';
    case 'stale': {
      const bucketSeconds = Math.round((freshness.ageBucketMs || 0) / 1000);
      return `stale, ${bucketSeconds}s`;
    }
    case 'failed': {
      const reason = freshness.reason || {};
      const label = reason.detail || reason.code || 'source failed';
      return freshness.lastGoodAsOf
        ? `source failed (${label}) - showing last good from ${freshness.lastGoodAsOf}`
        : `source failed (${label}) - no good data has ever been read`;
    }
    default:
      // Freshness is closed BY MECHANISM (design S5.2), but this module
      // never assumes a closed set holds at the wire boundary: an
      // unrecognised kind renders hot, by name - the same discovery
      // treatment applied to positions and outcomes elsewhere.
      return `unrecognised freshness: '${kind}'`;
  }
}

/**
 * Rule 2: position speaks first (primary line), freshness second;
 * not-applicable renders NO freshness line; missing capability says "no
 * renderer for this payload", never nothing.
 *
 * @param {{position: string, positionDefs: Array, freshness: object, hasRenderer: boolean}} args
 */
export function composeLines({ position, positionDefs, freshness, hasRenderer }) {
  const described = describeVocab(position, positionDefs);
  const primary = described.recognised ? described.label : `unrecognised position: '${position}'`;

  let secondary = freshnessLine(freshness);

  if (!hasRenderer) {
    secondary = secondary ? `${secondary} - ${NO_RENDERER_LINE}` : NO_RENDERER_LINE;
  }

  return { primary, secondary };
}

/* board.css - StarCar yard board (task 5.3). Industrial CTC-panel direction
   (mockup brief + the owner's 2b/1b merge): dark background, dense
   monospace typography, color rationed to exactly three registers.

   Steering deviation, disclosed: the mockup direction names IBM Plex Mono /
   Barlow Condensed specifically. This v0 pass uses system monospace /
   condensed-sans font STACKS with no network font fetch (no Google Fonts
   CDN), so the board is fully self-contained and renders offline/in CI
   with no external dependency. Swapping in the named webfonts is a pure
   CSS change whenever that's wanted - never a re-architecture.

   The one hard aesthetic law (mockup brief): three severity colors, total.
   Every other color in this file is background/structure/typography, never
   a fourth "shade of alarm". */

:root {
  --bg: #14181d;
  --panel: #1c2128;
  --border: #2c333d;
  --text: #d9d5c9; /* paper, mockup's nominal ink color */
  --text-dim: #8a8f97;

  --nominal: #d9d5c9;
  --in-progress: #ffb454; /* amber, mockup's in-progress color */
  --needs-attention: #ff4a3a; /* red, mockup's needs-attention color */
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'IBM Plex Mono', ui-monospace, 'Cascadia Mono', 'Consolas', monospace;
}

#board-root {
  max-width: 1400px;
  margin: 0 auto;
  padding: 1rem;
}

/* --- honesty chrome ------------------------------------------------- */

.chrome {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  padding: 0.5rem 0.75rem;
  border-bottom: 2px solid var(--border);
  margin-bottom: 1rem;
  font-family: 'Barlow Condensed', ui-sans-serif, system-ui, sans-serif;
  letter-spacing: 0.02em;
}

.demo-banner {
  background: var(--in-progress);
  color: #14181d;
  font-weight: 700;
  padding: 0.15rem 0.6rem;
  border-radius: 2px;
}

.connection-disconnected {
  color: var(--needs-attention);
  font-weight: 700;
}

.connection-connected {
  color: var(--text-dim);
}

.board-conditions {
  list-style: none;
  margin: 0.25rem 0 0 0;
  padding: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  font-size: 0.85rem;
}

.board-condition {
  padding: 0.1rem 0.4rem;
  border-left: 3px solid var(--border);
}

/* --- lanes ------------------------------------------------------------ */

.lanes {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.lane {
  background: var(--panel);
  border: 1px solid var(--border);
  border-left-width: 6px;
  border-radius: 3px;
  padding: 0.6rem 0.9rem;
}

.lane-title {
  font-family: 'Barlow Condensed', ui-sans-serif, system-ui, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin: 0 0 0.15rem 0;
  font-size: 1rem;
}

.lane-primary {
  font-weight: 600;
}

.lane-secondary {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 0.4rem;
}

/* --- the three registers, and NOTHING else colors an element ---------- */

.register-nominal {
  border-left-color: var(--nominal);
  color: var(--nominal);
}
.register-in-progress {
  border-left-color: var(--in-progress);
  color: var(--in-progress);
}
.register-needs-attention {
  border-left-color: var(--needs-attention);
  color: var(--needs-attention);
}

/* --- TRAINS / GATES: track-schematic direction (mockup 2b) ------------- */

.track {
  border-top: 2px solid var(--border);
  padding-top: 0.3rem;
  margin-top: 0.3rem;
}

.track-title {
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.track-cars {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.car-chip {
  display: flex;
  gap: 0.35rem;
  align-items: center;
  border: 1px solid var(--border);
  border-left: 4px solid currentColor;
  padding: 0.15rem 0.5rem;
  border-radius: 2px;
  font-size: 0.85rem;
}

.signal {
  display: flex;
  gap: 0.6rem;
  align-items: center;
  border: 1px solid var(--border);
  border-left: 4px solid currentColor;
  padding: 0.2rem 0.6rem;
  margin-top: 0.25rem;
  border-radius: 2px;
}

/* --- DISPATCHES: Solari split-flap direction (mockup 1b) --------------- */

.lane-body-dispatches {
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
}

.yard-inventory-count {
  color: var(--text-dim);
  font-size: 0.85rem;
  margin-bottom: 0.3rem;
}

.solari-rows {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.solari-row {
  display: flex;
  gap: 0.75rem;
  padding: 0.1rem 0.3rem;
  border-left: 3px solid currentColor;
}

.solari-row.unassigned {
  background: rgba(255, 255, 255, 0.03);
}

/* --- dark/bagged dignity: never hidden, never faked -------------------- */

.lane-body-dark,
.lane-body-bagged {
  color: var(--text-dim);
  font-style: italic;
  padding: 0.3rem 0;
}

.lane-body-no-renderer {
  color: var(--needs-attention);
}

// PB-7 (spec YB-4, plan task 5.3): the CLIENT-side half of "the SSE event
// name is a constant in the wire schema artifact, tested on both sides"
// (board/server's sse_const_test.go owns the server half). This test reads
// schema/yard-snapshot.schema.json directly and asserts the subscriber
// module's exported constant is EXACTLY $defs.sseEventName.const - never a
// hardcoded string with no tether back to the schema.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { SSE_EVENT_NAME } from '../js/wire-constants.js';

const thisDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = dirname(dirname(dirname(thisDir))); // board/web/test -> board/web -> board -> repo root
const schema = JSON.parse(readFileSync(join(repoRoot, 'schema', 'yard-snapshot.schema.json'), 'utf8'));

test('SSE_EVENT_NAME matches schema/yard-snapshot.schema.json\'s $defs.sseEventName.const EXACTLY', () => {
  assert.equal(schema.$defs.sseEventName.const, 'yard', 'fixture sanity: the schema constant itself must be "yard" for this test to mean anything');
  assert.equal(SSE_EVENT_NAME, schema.$defs.sseEventName.const);
});

// dom-writer.js - the ONLY module that touches the DOM. Takes render.js's
// pure view model and a `document`-shaped object (the real browser
// `document` in production; a minimal hand-rolled shim in
// board/web/test/dom-writer.test.js) and writes it into `root`.
//
// Deliberately uses only createElement/appendChild/textContent/className/
// setAttribute - the smallest DOM surface that can express this board -
// so the same code runs unmodified against Node's test shim (task 5.5's
// "render into a minimal DOM shim").
//
// Visual authority (plan task 5.3): the reviewed mockup brief
// (docs/design/2026-07-23-ui-mockup-brief.md) and design rev 5 S5.2's
// composition rules BIND (three registers only, verbatim words, honesty
// chrome, bagged/dark dignity); the 2b track-schematic (trains/gates) +
// 1b Solari-board (dispatches) mockup merge STEERS. This v0 pass renders
// the CONTRACTS fully and the steering direction structurally (track rows
// for trains/gates, dense monospace rows for dispatches) rather than
// pixel-for-pixel mockup fidelity - disclosed in this car's report as the
// conductor's first human look is the actual visual-polish gate.

function el(doc, tag, className, text) {
  const node = doc.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function registerClass(register) {
  return `register-${register}`;
}

/**
 * @param {Document} doc
 * @param {Element} root
 * @param {ReturnType<import('./render.js').buildBoardViewModel>} vm
 * @param {{connected: boolean}} connection
 */
export function renderBoard(doc, root, vm, connection) {
  root.textContent = ''; // clear() without needing a real DOM API for it

  root.appendChild(renderChrome(doc, vm, connection));

  const lanesRoot = el(doc, 'section', 'lanes');
  for (const lane of vm.lanes) {
    lanesRoot.appendChild(renderLane(doc, lane));
  }
  root.appendChild(lanesRoot);
}

function renderChrome(doc, vm, connection) {
  const chrome = el(doc, 'header', 'chrome');

  if (vm.demoMode) {
    chrome.appendChild(el(doc, 'div', 'demo-banner', 'DEMO DATA'));
  }

  chrome.appendChild(el(doc, 'div', 'as-of', `as of ${vm.asOf ?? '(no successful scan yet)'}`));

  const connectionClass = connection.connected ? 'connection-connected' : 'connection-disconnected';
  chrome.appendChild(
    el(doc, 'div', connectionClass, connection.connected ? 'connected' : 'disconnected - showing last known')
  );

  const laneCountText = `${vm.laneCompleteness.observed} of ${vm.laneCompleteness.declared} lanes`;
  chrome.appendChild(el(doc, 'div', 'lane-count', laneCountText));

  if (vm.boardConditions.length > 0) {
    const strip = el(doc, 'ul', 'board-conditions');
    for (const bc of vm.boardConditions) {
      strip.appendChild(el(doc, 'li', `board-condition ${registerClass(bc.register)}`, `${bc.code}: ${bc.detail}`));
    }
    chrome.appendChild(strip);
  }

  return chrome;
}

function renderLane(doc, lane) {
  const section = el(doc, 'article', `lane lane-${lane.id} ${registerClass(lane.register)}`);
  section.appendChild(el(doc, 'h2', 'lane-title', lane.title));
  section.appendChild(el(doc, 'div', 'lane-primary', lane.primary));
  if (lane.secondary) {
    section.appendChild(el(doc, 'div', 'lane-secondary', lane.secondary));
  }
  section.appendChild(renderLaneBody(doc, lane.body));
  return section;
}

function renderLaneBody(doc, body) {
  switch (body.kind) {
    case 'trains':
      return renderTrains(doc, body);
    case 'gates':
      return renderGates(doc, body);
    case 'dispatches':
      return renderDispatches(doc, body);
    case 'dark':
      return el(doc, 'div', 'lane-body lane-body-dark', body.text);
    case 'bagged':
      return el(doc, 'div', 'lane-body lane-body-bagged', body.text);
    case 'no-renderer':
      return el(doc, 'div', 'lane-body lane-body-no-renderer', 'no renderer for this payload');
    default:
      return el(doc, 'div', 'lane-body lane-body-unknown', `unrecognised lane body kind: '${body.kind}'`);
  }
}

// TRAINS: track-schematic direction (mockup merge 2b) - each train is a
// labeled track holding its cars in sequence.
function renderTrains(doc, body) {
  const wrap = el(doc, 'div', 'lane-body lane-body-trains');
  for (const train of body.trains) {
    const track = el(doc, 'div', 'track');
    track.appendChild(el(doc, 'div', 'track-title', `${train.title} (${train.id})`));
    const cars = el(doc, 'div', 'track-cars');
    for (const car of train.cars) {
      const chip = el(doc, 'div', `car-chip ${registerClass(car.stateRegister)}`);
      chip.appendChild(el(doc, 'span', 'car-subject', car.subject));
      chip.appendChild(el(doc, 'span', 'car-role', car.role.label));
      // VERBATIM state word - never translated (mockup brief).
      chip.appendChild(el(doc, 'span', 'car-state', car.state));
      if (car.outcome) {
        chip.appendChild(el(doc, 'span', `car-outcome ${registerClass(car.outcomeRegister)}`, car.outcome));
      }
      if (car.gate) {
        chip.appendChild(el(doc, 'span', 'car-gate', car.gate));
      }
      cars.appendChild(chip);
    }
    track.appendChild(cars);
    if (train.declaredNotObserved.length > 0) {
      track.appendChild(
        el(doc, 'div', 'declared-not-observed', `declared, not yet observed: ${train.declaredNotObserved.join(', ')}`)
      );
    }
    wrap.appendChild(track);
  }
  return wrap;
}

// GATES: signal-head direction (mockup merge 2b) - a small verdict light
// per gate, verdict word VERBATIM.
function renderGates(doc, body) {
  const wrap = el(doc, 'div', 'lane-body lane-body-gates');
  for (const gate of body.gates) {
    const signal = el(doc, 'div', `signal ${registerClass(gate.outcomeRegister)}`);
    signal.appendChild(el(doc, 'span', 'signal-name', gate.name));
    signal.appendChild(el(doc, 'span', 'signal-outcome', gate.outcome)); // VERBATIM
    signal.appendChild(el(doc, 'span', 'signal-at', gate.at));
    wrap.appendChild(signal);
  }
  return wrap;
}

// DISPATCHES: Solari split-flap direction (mockup merge 1b) - dense
// monospace rows: subject, state word, elapsed.
function renderDispatches(doc, body) {
  const wrap = el(doc, 'div', 'lane-body lane-body-dispatches');
  wrap.appendChild(
    el(doc, 'div', 'yard-inventory-count', `${body.yardInventoryCount} in yard inventory (unassigned)`)
  );
  const rows = el(doc, 'div', 'solari-rows');
  for (const d of body.dispatches) {
    const row = el(doc, 'div', `solari-row ${registerClass(d.stateRegister)}${d.assigned ? '' : ' unassigned'}`);
    row.appendChild(el(doc, 'span', 'solari-subject', d.subject));
    row.appendChild(el(doc, 'span', 'solari-state', d.state)); // VERBATIM
    if (d.elapsedSeconds !== null) {
      row.appendChild(el(doc, 'span', 'solari-elapsed', `${d.elapsedSeconds}s`));
    }
    rows.appendChild(row);
  }
  wrap.appendChild(rows);
  return wrap;
}

package assemble

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/polecatspeaks/StarCar/board/store"
)

// VocabDef mirrors schema/yard-snapshot.schema.json's $defs.vocabDef.
type VocabDef struct {
	ID       string `json:"id"`
	Label    string `json:"label"`
	Register string `json:"register"`
}

// Vocabularies mirrors the wire schema's top-level "vocabularies" property:
// presentational defs (label + register) for the recognition values that
// live as DATA in schema/vocab/*.json (Law 7 - this file adds presentation
// only, never a second recognition gate).
type Vocabularies struct {
	Positions []VocabDef `json:"positions"`
	Outcomes  []VocabDef `json:"outcomes"`
	Roles     []VocabDef `json:"roles"`
	Liveness  []VocabDef `json:"liveness"`
}

var closedRegisters = map[string]bool{"nominal": true, "in-progress": true, "needs-attention": true}

// LoadVocabularies reads schema/vocab/board-defs.json (task 2.4's pinned
// presentational defs). A missing/unreadable file is ONE board condition and
// empty vocabularies (non-fatal: the wire schema's own comment already
// legislates "a value with no def renders by raw id through the detector
// path"). A malformed INDIVIDUAL row - missing id/label/register, or a
// register outside the closed {nominal, in-progress, needs-attention} set -
// is skipped and named in its own condition; the rest of the file still
// loads (one bad row must not blank the whole vocabularies block).
func LoadVocabularies(path string) (Vocabularies, []store.BoardCondition) {
	data, err := os.ReadFile(path)
	if err != nil {
		return Vocabularies{}, []store.BoardCondition{{
			Code:     "board-defs-unreadable",
			Detail:   fmt.Sprintf("could not read %s: %v", path, err),
			Register: "needs-attention",
		}}
	}

	var raw struct {
		Positions []map[string]any `json:"positions"`
		Outcomes  []map[string]any `json:"outcomes"`
		Roles     []map[string]any `json:"roles"`
		Liveness  []map[string]any `json:"liveness"`
	}
	if err := json.Unmarshal(data, &raw); err != nil {
		return Vocabularies{}, []store.BoardCondition{{
			Code:     "board-defs-unreadable",
			Detail:   fmt.Sprintf("could not parse %s: %v", path, err),
			Register: "needs-attention",
		}}
	}

	var conditions []store.BoardCondition
	load := func(rows []map[string]any) []VocabDef {
		defs := make([]VocabDef, 0, len(rows))
		for _, row := range rows {
			id, _ := row["id"].(string)
			label, _ := row["label"].(string)
			register, _ := row["register"].(string)
			if id == "" || label == "" || !closedRegisters[register] {
				name := id
				if name == "" {
					name = fmt.Sprintf("%v", row)
				}
				conditions = append(conditions, store.BoardCondition{
					Code:     "board-def-invalid-row",
					Detail:   fmt.Sprintf("%s: row %q is invalid (missing id/label, or register outside the closed set)", path, name),
					Register: "needs-attention",
				})
				continue
			}
			defs = append(defs, VocabDef{ID: id, Label: label, Register: register})
		}
		return defs
	}

	return Vocabularies{
		Positions: load(raw.Positions),
		Outcomes:  load(raw.Outcomes),
		Roles:     load(raw.Roles),
		Liveness:  load(raw.Liveness),
	}, conditions
}

